// Process Twitter Data
const twitterData = $input.first().json;
const processedTwitter = {
  platform: 'Twitter',
  timestamp: new Date().toISOString(),
  metrics: {
    tweets_analyzed: twitterData.length || 0,
    total_likes: 0,
    total_retweets: 0,
    total_replies: 0,
    engagement_rate: 0
  }
};

if (Array.isArray(twitterData)) {
  twitterData.forEach(tweet => {
    processedTwitter.metrics.total_likes += tweet.favorite_count || 0;
    processedTwitter.metrics.total_retweets += tweet.retweet_count || 0;
    processedTwitter.metrics.total_replies += tweet.reply_count || 0;
  });

  const totalEngagements = processedTwitter.metrics.total_likes + 
                           processedTwitter.metrics.total_retweets + 
                           processedTwitter.metrics.total_replies;
  processedTwitter.metrics.engagement_rate = 
    (totalEngagements / processedTwitter.metrics.tweets_analyzed * 100).toFixed(2);
}

return { json: processedTwitter };

// Process Facebook Data
const facebookData = $input.first().json;
const processedFacebook = {
  platform: 'Facebook',
  timestamp: new Date().toISOString(),
  metrics: {
    page_impressions: 0,
    engaged_users: 0,
    post_engagements: 0,
    engagement_rate: 0
  }
};

if (facebookData.data && Array.isArray(facebookData.data)) {
  facebookData.data.forEach(metric => {
    if (metric.name === 'page_impressions') {
      processedFacebook.metrics.page_impressions = metric.values[0]?.value || 0;
    } else if (metric.name === 'page_engaged_users') {
      processedFacebook.metrics.engaged_users = metric.values[0]?.value || 0;
    } else if (metric.name === 'page_post_engagements') {
      processedFacebook.metrics.post_engagements = metric.values[0]?.value || 0;
    }
  });

  if (processedFacebook.metrics.page_impressions > 0) {
    processedFacebook.metrics.engagement_rate = 
      (processedFacebook.metrics.post_engagements / processedFacebook.metrics.page_impressions * 100).toFixed(2);
  }
}

return { json: processedFacebook };

// Process Instagram Data
const instagramData = $input.first().json;
const processedInstagram = {
  platform: 'Instagram',
  timestamp: new Date().toISOString(),
  metrics: {
    impressions: 0,
    reach: 0,
    follower_count: 0,
    profile_views: 0,
    engagement_rate: 0
  }
};

if (instagramData.data && Array.isArray(instagramData.data)) {
  instagramData.data.forEach(metric => {
    if (metric.name === 'impressions') {
      processedInstagram.metrics.impressions = metric.values[0]?.value || 0;
    } else if (metric.name === 'reach') {
      processedInstagram.metrics.reach = metric.values[0]?.value || 0;
    } else if (metric.name === 'follower_count') {
      processedInstagram.metrics.follower_count = metric.values[0]?.value || 0;
    } else if (metric.name === 'profile_views') {
      processedInstagram.metrics.profile_views = metric.values[0]?.value || 0;
    }
  });

  if (processedInstagram.metrics.impressions > 0) {
    processedInstagram.metrics.engagement_rate = 
      (processedInstagram.metrics.profile_views / processedInstagram.metrics.impressions * 100).toFixed(2);
  }
}

return { json: processedInstagram };

// Combine and format data for Google Sheets
const allData = $input.all();
const formattedRows = [];

allData.forEach(item => {
  const data = item.json;
  formattedRows.push({
    timestamp: data.timestamp,
    platform: data.platform,
    ...data.metrics
  });
});

// Calculate aggregate metrics
const aggregate = {
  timestamp: new Date().toISOString(),
  platform: 'AGGREGATE',
  total_impressions: 0,
  total_engagements: 0,
  average_engagement_rate: 0
};

let totalEngagementRate = 0;
let platformCount = 0;

formattedRows.forEach(row => {
  if (row.page_impressions) aggregate.total_impressions += row.page_impressions;
  if (row.impressions) aggregate.total_impressions += row.impressions;
  if (row.post_engagements) aggregate.total_engagements += row.post_engagements;
  if (row.engagement_rate) {
    totalEngagementRate += parseFloat(row.engagement_rate);
    platformCount++;
  }
});

if (platformCount > 0) {
  aggregate.average_engagement_rate = (totalEngagementRate / platformCount).toFixed(2);
}

formattedRows.push(aggregate);

return formattedRows.map(row => ({ json: row }));
